parameters.jsCode:
// Extract phone number, message text, and property code from OpenWA webhook payload
const entry = $input.first().json;

// OpenWA sends body.data for message.received events
const dataObj = entry.body?.data || entry.data || entry.payload || entry.message || entry;
const sessionId = entry.sessionId || 'e92af797-f78c-4ae5-ad10-eac6d2e10274';

// Extract raw sender and text safely
let rawFrom = dataObj.from || dataObj.sender?.id || dataObj.chatId || entry.from || '';
let rawText = dataObj.body || dataObj.text || dataObj.content || (typeof dataObj.message === 'string' ? dataObj.message : '') || '';

// Safely ensure text is a string
let text = typeof rawText === 'string' ? rawText : String(rawText || '');

// Candidate fields that may contain the user's real phone number
const candidateFields = [
  dataObj.sender?.phoneNumber,
  dataObj.sender?.phone,
  dataObj.sender?.user,
  dataObj.chat?.contact?.phoneNumber,
  dataObj.chat?.contact?.id,
  dataObj.chat?.id,
  dataObj.chatId,
  dataObj.author,
  dataObj.sender?.id,
  dataObj.from,
  entry.from
];

let phone = '';
let lidJid = '';

// 1. First pass: Find any candidate field that contains a valid 10 to 13-digit phone number (skipping @lid JIDs)
for (const cand of candidateFields) {
  if (!cand) continue;
  const str = String(cand).trim();

  if (str.includes('@lid') || (str.replace(/@.*$/, '').replace(/[^0-9]/g, '').length > 13)) {
    if (!lidJid) lidJid = str;
    continue;
  }

  const digits = str.replace(/@.*$/, '').replace(/[^0-9]/g, '');
  if (digits.length >= 10 && digits.length <= 13) {
    phone = digits;
    break;
  }
}

// 2. If LID detected (isLidSender = true) and no direct phone found, resolve LID -> Phone via WhatsApp Gateway API
if (!phone && lidJid) {
  const cleanLid = lidJid.includes('@') ? lidJid : `${lidJid}@lid`;
  try {
    const res = await helpers.httpRequest({
      method: 'GET',
      url: `https://letsellr-wa.letsellr.in/api/sessions/${sessionId}/contacts/${cleanLid}`,
      headers: {
        'X-API-Key': 'owa_k1_b9e0d0c24b491af4c0a8c68d0af3b61b2aea76af6321df8ba4419c46eb8e6e7d'
      },
      json: true,
      timeout: 5000
    });

    if (res && res.id && res.id.includes('@c.us')) {
      phone = res.id.replace(/@.*$/, '').replace(/[^0-9]/g, '');
    }
  } catch (err) {
    try {
      const res = await fetch(`https://letsellr-wa.letsellr.in/api/sessions/${sessionId}/contacts/${cleanLid}`, {
        headers: {
          'X-API-Key': 'owa_k1_b9e0d0c24b491af4c0a8c68d0af3b61b2aea76af6321df8ba4419c46eb8e6e7d'
        }
      });
      const data = await res.json();
      if (data && data.id && data.id.includes('@c.us')) {
        phone = data.id.replace(/@.*$/, '').replace(/[^0-9]/g, '');
      }
    } catch (e) {}
  }
}

// 3. Fallback: If still no phone found, clean rawFrom digits
if (!phone) {
  const rawDigits = rawFrom.replace(/@.*$/, '').replace(/[^0-9]/g, '');
  phone = rawDigits.length > 13 ? rawDigits.slice(-10) : rawDigits;
}

let propertyCode = null;

const refMatch = text.match(/(?:Ref|Reference|Code):?\s*([A-Z0-9-]+)\b/i);
if (refMatch) {
  propertyCode = refMatch[1].toUpperCase().replace(/[^A-Z0-9-]/g, '');
} else {
  const codeMatch = text.match(/\b(PROP-[A-Z0-9-]+|[A-Z]{2,4}\d{3,6})\b/i);
  if (codeMatch) {
    propertyCode = codeMatch[1].toUpperCase();
  }
}

return [{
  json: {
    phone_number: phone,
    raw_chat_id: rawFrom.includes('@') ? rawFrom : `${phone}@c.us`,
    message_text: text,
    property_code: propertyCode,
    session_id: `${phone}_${propertyCode || 'unknown'}`
  }
}];

// Recover property code from active session if message text did not contain one
const extracted = $('Extract Property Code').first().json;
const activeSession = $input.first().json;

let finalPropertyCode = extracted.property_code;
let finalSessionId = extracted.session_id;
let isNewEnquiry = false;

const activeCode = (activeSession?.property_code || '').trim().toUpperCase();
const newCode = (extracted?.property_code || '').trim().toUpperCase();

if (newCode && (!activeCode || activeCode !== newCode)) {
  isNewEnquiry = true;
  finalPropertyCode = newCode;
} else if (!finalPropertyCode && activeCode) {
  finalPropertyCode = activeCode;
  finalSessionId = activeSession.session_id || `${extracted.phone_number}_${activeCode}`;
  isNewEnquiry = false;
}

return [{
  json: {
    phone_number: extracted.phone_number,
    message_text: extracted.message_text,
    property_code: finalPropertyCode || null,
    session_id: finalSessionId,
    is_new_enquiry: isNewEnquiry
  }
}];

// Strip intent token from reply, capture intent flag
const raw = $input.first().json.output || '';
const confirmed = raw.includes('[INTENT:CONFIRMED]');
const cleanText = raw.replace(/\[INTENT:(CONFIRMED|OPEN)\]/g, '').trim();

return [{
  json: {
    ...$('Resolve Property Code').first().json,
    reply_text: cleanText,
    intent_confirmed: confirmed
  }
}];

parameters.query:
SELECT message FROM chat_sessions_memory
WHERE session_id = '{{ $('Resolve Property Code').first().json.session_id }}'
ORDER BY id ASC;

parameters.jsCode:
// Combine all transcript items into 1 single output item
const allItems = $input.all();
const messages = allItems.map(item => {
  const msg = item.json.message;
  if (!msg) return '';
  if (typeof msg === 'string') return msg;
  if (msg.data?.content) return `${msg.type || 'chat'}: ${msg.data.content}`;
  return JSON.stringify(msg);
}).filter(Boolean);

return [{
  json: {
    transcript_text: messages.join('\n')
  }
}];

// Parse Gemini's JSON summary output, guard against markdown fences
const first = $input.first().json;
const raw = typeof first === 'string' ? first : (first.text || first.content?.[0]?.text || first.output || JSON.stringify(first));
const clean = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { summary: clean, outcome: 'no', next_step: 'Review manually - parse failed' };
}

return [{
  json: {
    ...$('Parse Intent Token').first().json,
    summary: parsed.summary,
    outcome: parsed.outcome,
    next_step: parsed.next_step
  }
}];

parameters.query:
UPDATE chat_sessions
SET status = 'closed', outcome = '{{ $json.outcome || 'no' }}', summary = '{{ ($json.summary || '').replace(/'/g, "''") }}', updated_at = now()
WHERE session_id = '{{ $('Resolve Property Code').first().json.session_id }}';

parameters.text:
=Summarize this WhatsApp leasing conversation transcript into a JSON object.

Transcript:
{{ $json.transcript_text }}

Return ONLY a raw valid JSON object with no extra text or markdown formatting outside the JSON, matching this schema:
{
  "summary": "Short 1-2 sentence summary of the inquiry",
  "outcome": "yes" or "no",
  "next_step": "Next action for leasing team"
}

parameters.jsonBody:
={{ JSON.stringify({
  chatId: (() => {
    const d = $('Fetch Property Details').first().json || {};
    let p = String(d.owner_phone || d.owner_whatsapp || d.owner?.phone || '').replace(/[^0-9]/g, '');
    if (p.startsWith('0')) p = p.slice(1);
    if (p.length === 10) p = '91' + p;
    if (!p || p.length < 10) p = '918137090018';
    return p.includes('@') ? p : p + '@c.us';
  })(),
  text: (() => {
    const prop = $('Fetch Property Details').first().json || {};
    const user = $('Fetch User Profile').first().json || {};
    const extracted = $('Extract Property Code').first().json || {};
    const ownerName = prop.owner?.name || prop.owner_name || 'Property Owner';
    const tenantName = user.name || 'Valued Customer';
    const tenantPhone = user.phone || extracted.phone_number || '';
    const propTitle = prop.title || $('Resolve Property Code').first().json.property_code || '';
    const propRef = prop.ref || $('Resolve Property Code').first().json.property_code || '';
    return `🏡 *New Tenant Enquiry Confirmed!*

Hi ${ownerName},

A tenant has confirmed interest in your property *${propTitle}* (Code: *${propRef}*).

*Tenant Contact Details:*
• *Name:* ${tenantName}
• *Phone Number:* ${tenantPhone}

Please get in touch with them directly to arrange a visit or answer questions.`;
  })()
}) }}

={{ JSON.stringify({
  chatId: $('Extract Property Code').first().json.raw_chat_id,
  text: (() => {
    const prop = $('Fetch Property Details').first().json || {};
    const ownerName = prop.owner?.name || prop.owner_name || 'Property Owner';
    const ownerPhone = prop.owner_phone || prop.owner?.phone || prop.owner_whatsapp || 'Available upon request';
    const propTitle = prop.title || $('Resolve Property Code').first().json.property_code || '';

    let mapLink = '';
    if (prop.latitude && prop.longitude) {
      mapLink = `https://maps.google.com/?q=${prop.latitude},${prop.longitude}`;
    } else if (prop.location_address || prop.location_city) {
      const addr = [prop.location_address, prop.location_area, prop.location_city].filter(Boolean).join(', ');
      mapLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(addr)}`;
    }

    let text = `✅ *Owner Contact Details Shared!*

We have shared your enquiry with the property owner (*${ownerName}*).

*Owner Details:*
• *Name:* ${ownerName}
• *Phone Number:* ${ownerPhone}`;
    if (mapLink) {
      text += `
• *Location:* ${mapLink}`;
    }
    text += `

They will reach out to you shortly regarding *${propTitle}*.`;
    return text;
  })()
}) }}
